  public int RemotePeers{get{lock(gate)return remotePeers.Count;}}
  public static string Secret(){byte[] b=new byte[24];using(var r=RandomNumberGenerator.Create())r.GetBytes(b);return BitConverter.ToString(b).Replace("-","").ToLowerInvariant();}
  public Bridge(string inbox){Inbox=System.IO.Path.GetFullPath(inbox);Directory.CreateDirectory(Inbox);byte[] b=new byte[4];using(var r=RandomNumberGenerator.Create())r.GetBytes(b);Code=(BitConverter.ToUInt32(b,0)%900000+100000).ToString();}
  public List<SharedFile> Files {get{lock(gate)return files.Values.ToList();}}
  public void Share(string path){path=System.IO.Path.GetFullPath(path);if(!File.Exists(path))return;var info=new FileInfo(path);lock(gate){if(files.Values.Any(f=>String.Equals(f.Path,path,StringComparison.OrdinalIgnoreCase)))return;var file=new SharedFile{Id=Secret(),Path=path,Name=info.Name,Size=info.Length};files[file.Id]=file;}Log("Shared for phone download: "+info.Name);}
  public void Unshare(string id){lock(gate)files.Remove(id);}
  public void Start(string address){if(Running)return;if(!Admin)throw new InvalidOperationException("Administrator approval is required to open this local Windows listener.");IPAddress ip;if(!IPAddress.TryParse(address,out ip)||ip.AddressFamily!=AddressFamily.InterNetwork)throw new ArgumentException("Select a local IPv4 address.");Address="http://"+ip+":"+Port+"/";listener=new HttpListener();listener.Prefixes.Add(Address);try{listener.Start();AddFirewall(ip.ToString());Running=true;Task.Run((Action)Accept);Log("Sharing started. Phone: "+Address+" | Pairing code: "+Code);}catch{Dispose();throw;}}
  void AddFirewall(string ip){dynamic policy=Activator.CreateInstance(Type.GetTypeFromProgID("HNetCfg.FwPolicy2"));firewallName="PocketBridge.Local."+Process.GetCurrentProcess().Id+"."+Guid.NewGuid().ToString("N");dynamic r=Activator.CreateInstance(Type.GetTypeFromProgID("HNetCfg.FWRule"));r.Name=firewallName;r.Grouping="PocketBridge.Session";r.Description="Temporary HTTP.sys listener: selected local IP, TCP 48321, local subnet only. Removed when PocketBridge stops.";r.Protocol=6;r.LocalPorts=Port.ToString();r.LocalAddresses=ip;r.RemoteAddresses="LocalSubnet";r.Direction=1;r.Action=1;r.Profiles=7;r.Enabled=true;policy.Rules.Add(r);}
  async void Accept(){while(Running){HttpListenerContext c;try{c=await listener.GetContextAsync();}catch{break;}if(!slots.Wait(0)){Reply(c,503,new{error="Busy with other transfers. Please retry shortly."});continue;}Task.Run(()=>{try{Handle(c);}catch(Exception e){try{Reply(c,500,new{error="Transfer interrupted: "+e.Message});}catch{}Log("Transfer error: "+e.Message);}finally{try{c.Response.Close();}catch{}slots.Release();}});}}
  void Reply(HttpListenerContext c,int status,object obj){byte[] b=Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(obj));c.Response.StatusCode=status;c.Response.ContentType="application/json; charset=utf-8";c.Response.ContentLength64=b.Length;c.Response.OutputStream.Write(b,0,b.Length);c.Response.Close();}
  void Headers(HttpListenerContext c){c.Response.Headers["Cache-Control"]="no-store";c.Response.Headers["X-Content-Type-Options"]="nosniff";c.Response.Headers["X-Frame-Options"]="DENY";c.Response.Headers["Referrer-Policy"]="no-referrer";c.Response.Headers["Content-Security-Policy"]="default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; frame-ancestors 'none'; base-uri 'none'; form-action 'self'";}
