  bool SameOrigin(HttpListenerContext c){string origin=c.Request.Headers["Origin"];return !String.IsNullOrEmpty(origin)&&String.Equals(origin,Address.TrimEnd('/'),StringComparison.OrdinalIgnoreCase);}
  void Handle(HttpListenerContext c){Headers(c);string path=c.Request.Url.AbsolutePath,method=c.Request.HttpMethod;
