  public static string SafeName(string name){name=(name??"").Replace('\\','/');name=System.IO.Path.GetFileName(name);foreach(char ch in System.IO.Path.GetInvalidFileNameChars())name=name.Replace(ch,'_');name=name.Trim().TrimEnd('.');if(name.Length>140)name=name.Substring(0,140);if(String.IsNullOrWhiteSpace(name))name="Phone file";string stem=System.IO.Path.GetFileNameWithoutExtension(name).ToUpperInvariant();if(new[]{"CON","PRN","AUX","NUL","COM1","COM2","COM3","COM4","COM5","COM6","COM7","COM8","COM9","LPT1","LPT2","LPT3","LPT4","LPT5","LPT6","LPT7","LPT8","LPT9"}.Contains(stem))name="_"+name;return name;}
  void Upload(HttpListenerContext c,string relative=null){long expected=c.Request.ContentLength64;if(expected<0||expected>MaxFile)throw new IOException("Send files with a known size, up to 8 GiB per file.");string destination=Inbox;if(relative!=null){relative=PhoneLibrary.SafeRelative(relative);destination=System.IO.Path.GetFullPath(System.IO.Path.Combine(Inbox,System.IO.Path.GetDirectoryName(relative.Replace('/',System.IO.Path.DirectorySeparatorChar))??""));if(destination!=Inbox&&!destination.StartsWith(Inbox+System.IO.Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Destination outside Inbox.");Directory.CreateDirectory(destination);}string name=SafeName(relative==null?c.Request.QueryString["name"]:relative);string temp=System.IO.Path.Combine(destination,".pb-"+Secret()+".partial");Interlocked.Increment(ref transfers);try{long copied=0;using(var target=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] buffer=new byte[65536];int read;while((read=c.Request.InputStream.Read(buffer,0,buffer.Length))>0){if(!Running)throw new IOException("Sharing stopped.");copied+=read;if(copied>expected||copied>MaxFile)throw new IOException("File exceeds declared size.");target.Write(buffer,0,read);}target.Flush(true);}if(copied!=expected)throw new IOException("Upload incomplete; partial file discarded.");string final=null;lock(gate){string baseName=System.IO.Path.GetFileNameWithoutExtension(name),ext=System.IO.Path.GetExtension(name);for(int i=0;i<10000;i++){string candidate=System.IO.Path.Combine(destination,i==0?name:baseName+" ("+i+")"+ext);if(File.Exists(candidate))continue;try{File.Move(temp,candidate);final=candidate;break;}catch(IOException){if(!File.Exists(candidate))throw;}}}if(final==null)throw new IOException("Could not choose an unused filename.");Log("Received from phone: "+System.IO.Path.GetFileName(final)+" · "+copied+" bytes");Reply(c,200,new{ok=true,name=System.IO.Path.GetFileName(final),bytes=copied