  public void Dispose(){Running=false;if(listener!=null){try{listener.Close();}catch{}listener=null;}Phone.Clear();lock(gate)sessions.Clear();if(firewallName!=null)try{dynamic policy=Activator.CreateInstance(Type.GetTypeFromProgID("HNetCfg.FwPolicy2"));policy.Rules.Remove(firewallName);firewallName=null;}catch(Exception e){Log("Could not remove temporary firewall rule: "+e.Message+". Use Windows Firewall to remove PocketBridge.Session rules if needed.");}}
