  public int NetworkCount{get{return networks.Items.Count;}}
  void Networks(){string previous=networks.SelectedItem as string;networks.Items.Clear();foreach(var n in NetworkInterface.GetAllNetworkInterfaces().Where(n=>n.OperationalStatus==OperationalStatus.Up&&n.NetworkInterfaceType!=NetworkInterfaceType.Loopback).OrderBy(n=>n.NetworkInterfaceType==NetworkInterfaceType.Wireless80211?0:1))foreach(var a in n.GetIPProperties().UnicastAddresses.Where(a=>a.Address.AddressFamily==AddressFamily.InterNetwork&&!a.Address.ToString().StartsWith("169.254.")))networks.Items.Add(a.Address.ToString()+" | "+n.Name);if(previous!=null&&networks.Items.Contains(previous))networks.SelectedItem=previous;else if(networks.Items.Count>0)networks.SelectedIndex=0;if(state!=null)state.Text="Address scan complete at "+DateTime.Now.ToString("HH:mm:ss")+": "+networks.Items.Count+" usable interface(s). This rescans Windows addresses; it does not turn hotspot/Wi-Fi on.";}
  void Log(string message){if(IsDisposed)return;try{if(InvokeRequired){BeginInvoke((Action)(()=>Log(message)));return;}if(log.TextLength>50000)log.Clear();log.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+message+Environment.NewLine);}catch{}}
