  void Stop(){if(bridge.Active>0&&MessageBox.Show(this,"Stop will interrupt active transfers. Continue?","Stop sharing",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;var old=bridge.Files;bridge.Dispose();bridge=new Bridge(inbox);bridge.Log=Log;foreach(var f in old)bridge.Share(f.Path);start.Enabled=true;stop.Enabled=false;networks.Enabled=true;address.Text="Phone connection is stopped";code.Text="Code: —";if(qrBox.Image!=null){qrBox.Image.Dispose();qrBox.Image=null;}phoneFolder="";phoneSignature="";RenderPhone();connection.Text="Stopped. Phone browsers disconnected; start again for a new pairing code.";state.Text="Stopped. Browsers disconnected; pairing code regenerated.";}
  void UpdateConnection(){if(!bridge.Running)return;connection.ForeColor=bridge.Phone.Online?Color.FromArgb(8,127,90):Color.FromArgb(145,90,10);connection.Text=bridge.Phone.Online?"PHONE SELECTION ONLINE • "+bridge.Phone.Files.Count+" shared files. Browse them in the PHONE selection tab.":bridge.RemotePeers>0?"REMOTE DEVICE REACHED • Pair on the phone, then select files/folder and tap Share selection with laptop.":"WAITING FOR PHONE • Server is running. Scan this QR using your PHONE camera; no phone has reached it yet.";state.Text="SERVER ON • "+bridge.RemotePeers+" remote device(s) seen • "+bridge.Active+" transfer(s) • Inbox: "+inbox;string signature=String.Join("|",bridge.Phone.Files.Select(f=>f.id));if(signature!=phoneSignature){phoneSignature=signature;phoneFolder="";RenderPhone();}}
  void RenderPhone(){phoneList.Items.Clear();var files=bridge.Phone.Files;folderLabel.Text=files.Count==0?"On PHONE: pair → select files/folder → Share selection with laptop.":"Phone selection / "+phoneFolder+"    (double-click folders; tick files/folders to copy)";var directories=new HashSet<string>();foreach(var f in files.Where(f=>f.path.StartsWith(phoneFolder,StringComparison.Ordinal))){string rest=f.path.Substring(phoneFolder.Length);int slash=rest.IndexOf('/');if(slash>=0){string dir=rest.Substring(0,slash);if(directories.Add(dir)){var item=new ListViewItem(new[]{"[Folder] "+dir,""});item.Tag=phoneFolder+dir+"/";phoneList.Items.Add(item);}}else{var item=new ListViewItem(new[]{rest,(f.size/1048576.0).ToString("N1")+" MiB"});item.Tag=f;phoneList.Items.Add(item);}}}
  void CopyPhone(){var ids=new HashSet<string>();foreach(ListViewItem item in phoneList.CheckedItems){var f=item.Tag as PhoneFile;if(f!=null)ids.Add(f.id);else foreach(var entry in bridge.Phone.Files.Where(entry=>entry.path.StartsWith((string)item.Tag,StringComparison.Ordinal)))ids.Add(entry.id);}if(ids.Count==0)throw new Exception("Tick phone files or folders first. Share them from the PHONE browser if this list is empty.");int count=bridge.Phone.Queue(ids);Log(count+" phone file(s) requested. Keep the phone page awake; received folder structure is preserved in the Inbox.");}
  void ConnectionHelp(){MessageBox.Show(this,"1. Your laptop must be connected to the PHONE's hotspot; keep phone mobile data OFF.\n2. Enable & connect phone, accept Windows UAC. The new window now starts the server automatically.\n3. Scan the QR with your PHONE camera and open the HTTP link (not HTTPS).\n4. Enter the code on PHONE. The dashboard must show REMOTE DEVICE REACHED.\n5. To browse from laptop: select phone files/folder there and Share selection with laptop. Keep that page open.\n\nRescan addresses shows local adapter addresses, not nearby Wi-Fi networks. If it reports the same address, the connection has not changed.\n\nIf the phone cannot open the link: temporarily disconnect a VPN on either device, check DataGate/other explicit blocks, and verify the selected adapter. PocketBridge does not remove your other firewall rules.\n\nFull unselected Android storage browsing requires a separately installed Android companion with folder permissions; this Windows-only browser workflow cannot provide it.","Connect your PHONE — local only",MessageBoxButtons.OK,MessageBoxIcon.Information);}
  void Add(){using(var d=new OpenFileDialog{Multiselect=true,Title="Select laptop files to offer to your phone"})if(d.ShowDialog(this)==DialogResult.OK){foreach(string file in d.FileNames)bridge.Share(file);Render();}}
 }
 static class Program {
  static Program(){AppDomain.CurrentDomain.AssemblyResolve+=(sender,args)=>{if(new System.Reflection.AssemblyName(args.Name).Name!="QRCoder")return null;using(var stream=typeof(Program).Assembly.GetManifestResourceStream("QRCoder.dll"))using(var memory=new MemoryStream()){stream.CopyTo(memory);return System.Reflection.Assembly.Load(memory.ToArray());}};}
  [STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{if(args.Contains("--install")){Install();return 0;}if(args.Contains("--retire-older")){if(!Bridge.Admin)throw new Exception("Administrator approval is required to close older elevated dashboards.");string root=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","PocketBridge")+"\\";foreach(var p in Process.GetProcessesByName("PocketBridge"))using(p)try{if(p.Id!=Process.GetCurrentProcess().Id&&p.MainWindowHandle!=IntPtr.Zero&&p.MainModule.FileName.StartsWith(root,StringComparison.OrdinalIgnoreCase)&&!String.Equals(p.MainModule.FileName,Application.ExecutablePath,StringComparison.OrdinalIgnoreCase))p.CloseMainWindow();}catch{}return 0;}if(args.Contains("--self-test")){Tests();return 0;}if(args.Contains("--server-test")){ServerTest();return 0;}if(args.Contains("--preview")){using(var f=new Window()){f.Show();Application.DoEvents();using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(0,0,image.Width,image.Height));image.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"preview.png"));}}return 0;}if(System.IO.Path.GetFileNameWithoutExtension(Application.ExecutablePath)=="PocketBridge-Setup"){Install();Process.Start(new ProcessStartInfo(Installed()){UseShellExecute=true});return 0;}var window=new Window();int index=Array.IndexOf(args,"--shares");if(index>=0&&index+1<args.Length)window.RestoreShares(args[index+1]);index=Array.IndexOf(args,"--address");if(index>=0&&index+1<args.Length)window.SelectAddress(args[index+1]);if(args.Contains("--start"))window.Shown+=(s,e)=>window.BeginInvoke((Action)window.AutoStart);Application.Run(window);return 0;}catch(Exception e){if(args.Any(a=>a.EndsWith("test")))File.WriteAllText(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-error.txt"),e.ToString());else MessageBox.Show(e.Message,"PocketBridge");return 1;}}
  static string Installed(){return System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","PocketBridge","versions","1.1.0","PocketBridge.exe");}
  static void Install(){string exe=Installed();Directory.CreateDirectory(System.IO.Path.GetDirectoryName(exe));if(!String.Equals(exe,Application.ExecutablePath,StringComparison.OrdinalIgnoreCase))File.Copy(Application.ExecutablePath,exe,true);dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));foreach(string folder in new[]{Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),Environment.GetFolderPath(Environment.SpecialFolder.Programs)}){dynamic link=shell.CreateShortcut(System.IO.Path.Combine(folder,"PocketBridge.lnk"));link.TargetPath=exe;link.WorkingDirectory=System.IO.Path.GetDirectoryName(exe);link.IconLocation=exe+",0";link.Save();}}
  static void Tests(){if(Bridge.SafeName("../../danger.txt")!="danger.txt"||Bridge.SafeName("CON.txt")!="_CON.txt"||Bridge.SafeName("x:y.txt").Contains(":"))throw new Exception("Filename sanitization failed");if(Bridge.Secret()==Bridge.Secret())throw new Exception("Random token collision");bool traversal=false;try{PhoneLibrary.SafeRelative("folder/../bad.txt");}catch(ArgumentException){traversal=true;}if(!traversal)throw new Exception("Phone folder traversal accepted");var library=new PhoneLibrary();library.Publish("owner",new PhoneSelection{device="Test phone",files=new List<PhoneFile>{new PhoneFile{id="a",path="Docs/test.txt",size=20}}});if(library.Queue(new[]{"a"})!=1||library.Poll("stranger").Count!=0||library.Poll("owner").Count!=1)throw new Exception("Phone file requests were not ownership scoped");if(library.Start("owner",library.Poll("owner")[0].id)!="Docs/test.txt")throw new Exception("Phone folder structure lost");using(var qr=Qr.Create("http://10.1.2.3:48321/")){if(qr.Width<100)throw new Exception("Offline QR rendering failed");}int networkCount;using(var f=new Window()){f.CreateControl();networkCount=f.NetworkCount;}File.WriteAllText(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-results.txt"),"PASS: filename sanitization; phone-folder traversal rejection; manifest/queue ownership; folder-path preservation; embedded offline QR renderer; native dashboard. Detected network addresses="+networkCount+". No firewall/network changes.");}
  static string Request(string url,string method,string body,CookieContainer cookies,string csrf=null){var r=(HttpWebRequest)WebRequest.Create(url);r.Proxy=null;r.Method=method;r.CookieContainer=cookies;r.Timeout=6000;if(method=="POST"){r.Headers["Origin"]=new Uri(url).GetLeftPart(UriPartial.Authority);if(csrf!=null)r.Headers["X-PocketBridge-CSRF"]=csrf;byte[] b=Encoding.UTF8.GetBytes(body??"");r.ContentLength=b.Length;using(var s=r.GetRequestStream())s.Write(b,0,b.Length);}using(var response=r.GetResponse())using(var reader=new StreamReader(response.GetResponseStream()))return reader.ReadToEnd();}
  static void ServerTest(){string dir=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"PocketBridge-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);using(var b=new Bridge(dir)){b.Start("127.0.0.1");var cookies=new CookieContainer();bool denied=false;try{Request(b.Address+"api/files","GET",null,cookies);}catch(WebException e){denied=((HttpWebResponse)e.Response).StatusCode==HttpStatusCode.Unauthorized;}if(!denied)throw new Exception("Unpaired access was not rejected");Request(b.Address+"pair","POST",b.Code,cookies);var serializer=new JavaScriptSerializer();var state=serializer.Deserialize<Dictionary<string,object>>(Request(b.Address+"api/files","GET",null,cookies));string token=(string)state["csrf"];Request(b.Address+"upload?name=hello.txt","POST","Local transfer test",cookies,token);Request(b.Address+"upload?name=hello.txt","POST","Second copy",cookies,token);if(File.ReadAllText(System.IO.Path.Combine(dir,"hello.txt"))!="Local transfer test"||!File.Exists(System.IO.Path.Combine(dir,"hello (1).txt")))throw new Exception("Upload or duplicate handling failed");b.Share(System.IO.Path.Combine(dir,"hello.txt"));if(Request(b.Address+"download/"+b.Files[0].Id,"GET",null,cookies)!="Local transfer test")throw new Exception("Download mismatch");bool csrfDenied=false;try{Request(b.Address+"upload?name=bad.txt","POST","bad",cookies);}catch(WebException e){csrfDenied=((HttpWebResponse)e.Response).StatusCode==HttpStatusCode.Forbidden;}if(!csrfDenied)throw new Exception("Missing CSRF was accepted");}File.WriteAllText(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"server-test.txt"),"PASS: local listener; unpaired rejection; pairing/cookie; CSRF protection; upload; duplicate preservation; byte-identical download; temporary firewall rule cleanup. Test data retained at "+dir);}
 }
